// Fictional scenario traffic. Kinematic motion, not aircraft or tactical validation.
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),wrap=x=>Math.atan2(Math.sin(x),Math.cos(x));
export class AircraftForces {
 constructor(){this.units=[];this.selected=null;this.serial=0;this.hits=0;this.mode='patrol';}
 reset(player){this.units=[];this.selected=null;this.serial=0;this.hits=0;if(player.aircraft?.key==='f15')this.spawn(player,'opposing');}
 clear(){this.units=[];this.selected=null;this.hits=0;}
 spawn(player,team='opposing'){if(this.units.filter(u=>u.alive).length>=4)return false;this.units=this.units.filter(u=>u.alive);const yaw=player.attitude.yaw,n=this.units.length,forward=900+n*350,side=150+n*250,position=[player.state[0]+Math.cos(yaw)*forward-Math.sin(yaw)*side,player.state[1]+Math.sin(yaw)*forward+Math.cos(yaw)*side,Math.min(player.state[2],-600)];const id=++this.serial,radius=750;
  this.units.push({id,name:(team==='friendly'?'BLUE':'RED')+' '+id,team:team==='friendly'?'friendly':'opposing',alive:true,position,center:[position[0]-Math.cos(yaw)*radius,position[1]-Math.sin(yaw)*radius,position[2]],angle:yaw,yaw:yaw+Math.PI/2,bank:.5,speed:110,velocity:[0,0,0],mode:'patrol',evade:0});return true;
 }
 cycle(){const ids=this.units.filter(u=>u.alive&&u.team==='opposing').map(u=>u.id);const i=ids.indexOf(this.selected);this.selected=ids.length?ids[(i+1)%ids.length]:null;return this.selected;}
 step(dt,player,missiles=[]){for(const u of this.units){if(!u.alive)continue;const threat=missiles.some(m=>m.targetId===u.id&&Math.hypot(...m.position.map((v,i)=>v-u.position[i]))<800);u.evade=threat?1:Math.max(0,u.evade-dt);const returning=Math.hypot(u.position[0]-u.center[0],u.position[1]-u.center[1])>2200;u.mode=u.evade?'evade':returning?'return':u.team==='opposing'&&this.mode==='intercept'?'intercept':'patrol';
  let goal;if(u.mode==='evade'){u.yaw+=dt*.6;u.bank=.8;}else{if(u.mode==='intercept')goal=player.state;else if(u.mode==='return')goal=u.center;else{u.angle+=dt*u.speed/750;goal=[u.center[0]+750*Math.cos(u.angle),u.center[1]+750*Math.sin(u.angle),u.center[2]];}
   const desired=Math.atan2(goal[1]-u.position[1],goal[0]-u.position[0]),turn=clamp(wrap(desired-u.yaw)*1.5,-.35,.35);u.yaw+=turn*dt;u.bank=clamp(turn*2,-.7,.7);}
  const altitude=goal?.[2]??u.center[2],down=clamp((Math.min(-300,altitude)-u.position[2])*.1,-15,15);u.velocity=[Math.cos(u.yaw)*u.speed,Math.sin(u.yaw)*u.speed,down];for(let i=0;i<3;i++)u.position[i]+=u.velocity[i]*dt;
 }if(this.selected&&!this.units.some(u=>u.alive&&u.id===this.selected))this.selected=null;}
 snapshot(player){const units=this.units.filter(u=>u.alive).map(u=>({id:u.id,name:u.name,team:u.team,position:u.position.slice(),yaw:u.yaw,bank:u.bank,mode:u.mode}));const target=units.find(u=>u.id===this.selected),delta=target?.position.map((v,i)=>v-player.state[i]),range=delta?Math.hypot(...delta):null;const yaw=player.attitude.yaw,pitch=player.attitude.pitch,forward=[Math.cos(yaw)*Math.cos(pitch),Math.sin(yaw)*Math.cos(pitch),-Math.sin(pitch)];const lock=Boolean(delta&&range>0&&range<5000&&delta.reduce((s,v,i)=>s+v*forward[i],0)/range>.65);return {units,selected:this.selected,range,lock,hits:this.hits,mode:this.mode};}
}
export function drawAircraftForces(g,forces,project,playerPosition){if(!forces)return;g.save();for(const u of forces.units.slice().sort((a,b)=>Math.hypot(...b.position.map((v,i)=>v-playerPosition[i]))-Math.hypot(...a.position.map((v,i)=>v-playerPosition[i])))){
 const color=u.team==='friendly'?'#87d5ff':'#ffae8e',world=p=>{const bank=u.bank,y=p[1]*Math.cos(bank)-p[2]*Math.sin(bank),z=p[1]*Math.sin(bank)+p[2]*Math.cos(bank);return [u.position[0]+p[0]*Math.cos(u.yaw)-y*Math.sin(u.yaw),u.position[1]+p[0]*Math.sin(u.yaw)+y*Math.cos(u.yaw),u.position[2]+z];};
 for(const points of [[[9,0,0],[-8,-1,0],[-8,1,0]],[[2,0,0],[-5,-7,0],[-7,-7,0],[-6,0,0],[-7,7,0],[-5,7,0]],[[-6,0,0],[-9,-3,0],[-10,0,0],[-9,3,0]],[[-5,0,0],[-9,0,-3],[-10,0,0]]]){const pts=points.map(p=>project(world(p)));if(pts.some(p=>!p))continue;g.fillStyle=u.team==='friendly'?'#8bb3c8':'#c5b0a3';g.strokeStyle='#394650';g.lineWidth=.7;g.beginPath();pts.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.closePath();g.fill();g.stroke();}
 const p=project(u.position);if(!p)continue;const selected=u.id===forces.selected;g.strokeStyle=selected&&forces.lock?'#b0ed8c':color;g.lineWidth=selected?2:1;g.strokeRect(p[0]-12,p[1]-12,24,24);g.fillStyle=color;g.font='14px monospace';g.textAlign='center';const range=Math.hypot(...u.position.map((v,i)=>v-playerPosition[i]))/1000;g.fillText(`${u.name} · ${range.toFixed(1)} km`,p[0],p[1]-19);if(selected){g.fillStyle=forces.lock?'#b0ed8c':color;g.fillText(forces.lock?'LOCK':'SELECTED',p[0],p[1]+29);}}
 g.restore();}
